const readPlan=():Plan=>{const fallback:Plan={from:'',originMode:'current_location',to:'',arrival:nowPlus(90),travel:35,buffer:5,arrivalBuffer:5,reserve:5,source:'수동 입력',context:'general'};const saved=load<Partial<Plan>>('adc-plan',{});return {...fallback,...saved,originMode:saved.originMode??(saved.from?'manual':'current_location'),context:saved.context??'general'}}
const fmt=(d:Date)=>d.toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit',hour12:false})
const dateLocal=(d:Date)=>{const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
